-- Images (2026-11-27, decision of the user): the logo and cover of a business, and up to 10
-- images of the best work of each professional. The files live in the media store (the server's
-- disk for now); the database keeps their keys, generated by the server.

-- +goose Up
ALTER TABLE businesses
    ADD COLUMN logo_key  text,
    ADD COLUMN cover_key text,
    ADD CONSTRAINT businesses_logo_key_valid CHECK (logo_key ~ '^logos/[0-9a-f-]{36}/[0-9a-f-]{36}\.(jpg|png)$'),
    ADD CONSTRAINT businesses_cover_key_valid CHECK (cover_key ~ '^covers/[0-9a-f-]{36}/[0-9a-f-]{36}\.(jpg|png)$');

CREATE TABLE professional_portfolio_images (
    id              uuid        PRIMARY KEY,
    business_id     uuid        NOT NULL,
    professional_id uuid        NOT NULL,
    storage_key     text        NOT NULL UNIQUE,
    caption         text        NOT NULL DEFAULT '',
    sort_order      integer     NOT NULL DEFAULT 0,
    width           integer     NOT NULL,
    height          integer     NOT NULL,
    created_by      uuid        NOT NULL REFERENCES users (id),
    created_at      timestamptz NOT NULL,
    updated_at      timestamptz NOT NULL,
    CONSTRAINT professional_portfolio_images_professional_fk FOREIGN KEY (business_id, professional_id)
        REFERENCES professionals (business_id, id) ON DELETE CASCADE,
    CONSTRAINT professional_portfolio_images_key_valid
        CHECK (storage_key ~ '^portfolio/[0-9a-f-]{36}/[0-9a-f-]{36}\.(jpg|png)$'),
    CONSTRAINT professional_portfolio_images_caption_length CHECK (char_length(caption) <= 140),
    CONSTRAINT professional_portfolio_images_sort_order_range CHECK (sort_order BETWEEN 0 AND 1000),
    CONSTRAINT professional_portfolio_images_size_valid CHECK (width > 0 AND height > 0)
);
CREATE INDEX professional_portfolio_images_professional_idx
    ON professional_portfolio_images (business_id, professional_id, sort_order, created_at);

-- +goose Down
DROP TABLE professional_portfolio_images;
ALTER TABLE businesses DROP COLUMN cover_key, DROP COLUMN logo_key;
